45	/// Slightly altered implementation from https://github.com/pocoproject/poco/blob/poco-1.6.1/Net/src/SocketAddress.cpp#L86
46	static void splitHostAndPort(const std::string & host_and_port, std::string & out_host, UInt16 & out_port)
47	{
48	    String port_str;
49	    out_host.clear();
50	
51	    auto it = host_and_port.begin();
52	    auto end = host_and_port.end();
53	
54	    if (*it == '[') /// Try parse case '[<IPv6 or something else>]:<port>'
55	    {
56	        ++it;
57	        while (it != end && *it != ']')
58	            out_host += *it++;
59	        if (it == end)
60	            throw Exception("Malformed IPv6 address", ErrorCodes::BAD_ARGUMENTS);
61	        ++it;
62	    }
63	    else /// Case '<IPv4 or domain name or something else>:<port>'
64	    {
65	        while (it != end && *it != ':')
66	            out_host += *it++;
67	    }
68	
69	    if (it != end && *it == ':')
70	    {
71	        ++it;
72	        while (it != end)
73	            port_str += *it++;
74	    }
75	    else
76	        throw Exception("Missing port number", ErrorCodes::BAD_ARGUMENTS);
77	
78	    unsigned port;
79	    if (Poco::NumberParser::tryParseUnsigned(port_str, port) && port <= 0xFFFF)
80	    {
81	        out_port = static_cast<UInt16>(port);
82	    }
83	    else
84	        throw Exception("Port must be numeric", ErrorCodes::BAD_ARGUMENTS);
85	}
