87	static DNSResolver::IPAddresses hostByName(const std::string & host)
88	{
89	    /// Family: AF_UNSPEC
90	    /// AI_ALL is required for checking if client is allowed to connect from an address
91	    auto flags = Poco::Net::DNS::DNS_HINT_AI_V4MAPPED | Poco::Net::DNS::DNS_HINT_AI_ALL;
92	    /// Do not resolve IPv6 (or IPv4) if no local IPv6 (or IPv4) addresses are configured.
93	    /// It should not affect client address checking, since client cannot connect from IPv6 address
94	    /// if server has no IPv6 addresses.
95	    flags |= Poco::Net::DNS::DNS_HINT_AI_ADDRCONFIG;
96	
97	    DNSResolver::IPAddresses addresses;
98	
99	    try
100	    {
101	        addresses = Poco::Net::DNS::hostByName(host, flags).addresses();
102	    }
103	    catch (const Poco::Net::DNSException & e)
104	    {
105	        LOG_ERROR(&Poco::Logger::get("DNSResolver"), "Cannot resolve host ({}), error {}: {}.", host, e.code(), e.name());
106	        addresses.clear();
107	    }
108	
109	    if (addresses.empty())
110	    {
111	        ProfileEvents::increment(ProfileEvents::DNSError);
112	        throw Exception("Not found address of host: " + host, ErrorCodes::DNS_ERROR);
113	    }
114	
115	    return addresses;
116	}
