118	static DNSResolver::IPAddresses resolveIPAddressImpl(const std::string & host)
119	{
120	    Poco::Net::IPAddress ip;
121	
122	    /// NOTE:
123	    /// - Poco::Net::DNS::resolveOne(host) doesn't work for IP addresses like 127.0.0.2
124	    /// - Poco::Net::IPAddress::tryParse() expect hex string for IPv6 (without brackets)
125	    if (host.starts_with('['))
126	    {
127	        assert(host.ends_with(']'));
128	        if (Poco::Net::IPAddress::tryParse(host.substr(1, host.size() - 2), ip))
129	            return DNSResolver::IPAddresses(1, ip);
130	    }
131	    else
132	    {
133	        if (Poco::Net::IPAddress::tryParse(host, ip))
134	            return DNSResolver::IPAddresses(1, ip);
135	    }
136	
137	    DNSResolver::IPAddresses addresses = hostByName(host);
138	
139	    return addresses;
140	}
