142	static Strings reverseResolveImpl(const Poco::Net::IPAddress & address)
143	{
144	    auto ptr_resolver = DB::DNSPTRResolverProvider::get();
145	
146	    if (address.family() == Poco::Net::IPAddress::Family::IPv4)
147	    {
148	        return ptr_resolver->resolve(address.toString());
149	    } else
150	    {
151	        return ptr_resolver->resolve_v6(address.toString());
152	    }
