220	std::vector<Poco::Net::SocketAddress> DNSResolver::resolveAddressList(const std::string & host, UInt16 port)
221	{
222	    if (Poco::Net::IPAddress ip; Poco::Net::IPAddress::tryParse(host, ip))
223	        return std::vector<Poco::Net::SocketAddress>{{ip, port}};
224	
225	    std::vector<Poco::Net::SocketAddress> addresses;
226	
227	    if (!impl->disable_cache)
228	        addToNewHosts(host);
229	
230	    std::vector<Poco::Net::IPAddress> ips = impl->disable_cache ? hostByName(host) : impl->cache_host(host);
231	    auto ips_end = std::unique(ips.begin(), ips.end());
232	
233	    addresses.reserve(ips_end - ips.begin());
234	    for (auto ip = ips.begin(); ip != ips_end; ++ip)
235	        addresses.emplace_back(*ip, port);
236	
237	    return addresses;
238	}
