284	template <typename UpdateF, typename ElemsT>
285	bool DNSResolver::updateCacheImpl(
286	    UpdateF && update_func,
287	    ElemsT && elems,
288	    UInt32 max_consecutive_failures,
289	    const String & notfound_log_msg,
290	    const String & dropped_log_msg)
291	{
292	    bool updated = false;
293	    String lost_elems;
294	    using iterators = typename std::remove_reference_t<decltype(elems)>::iterator;
295	    std::vector<iterators> elements_to_drop;
296	    for (auto it = elems.begin(); it != elems.end(); it++)
297	    {
298	        try
299	        {
300	            updated |= (this->*update_func)(it->first);
301	            it->second = 0;
302	        }
303	        catch (const DB::Exception & e)
304	        {
305	            if (e.code() != ErrorCodes::DNS_ERROR)
306	            {
307	                tryLogCurrentException(log, __PRETTY_FUNCTION__);
308	                continue;
309	            }
310	            if (!lost_elems.empty())
311	                lost_elems += ", ";
312	            lost_elems += cacheElemToString(it->first);
313	            if (max_consecutive_failures)
314	            {
315	                it->second++;
316	                if (it->second >= max_consecutive_failures)
317	                    elements_to_drop.emplace_back(it);
318	            }
319	        }
320	        catch (...)
321	        {
322	            tryLogCurrentException(log, __PRETTY_FUNCTION__);
323	        }
324	    }
325	
326	    if (!lost_elems.empty())
327	        LOG_INFO(log, fmt::runtime(notfound_log_msg), lost_elems);
328	    if (elements_to_drop.size())
329	    {
330	        updated = true;
331	        String deleted_elements;
332	        for (auto it : elements_to_drop)
333	        {
334	            if (!deleted_elements.empty())
335	                deleted_elements += ", ";
336	            deleted_elements += cacheElemToString(it->first);
337	            elems.erase(it);
338	        }
339	        LOG_INFO(log, fmt::runtime(dropped_log_msg), deleted_elements);
340	    }
341	
342	    return updated;
343	}
