345	bool DNSResolver::updateCache(UInt32 max_consecutive_failures)
346	{
347	    LOG_DEBUG(log, "Updating DNS cache");
348	
349	    {
350	        String updated_host_name = Poco::Net::DNS::hostName();
351	
352	        std::lock_guard lock(impl->drop_mutex);
353	
354	        for (const auto & host : impl->new_hosts)
355	            impl->known_hosts.insert(host);
356	        impl->new_hosts.clear();
357	
358	        for (const auto & address : impl->new_addresses)
359	            impl->known_addresses.insert(address);
360	        impl->new_addresses.clear();
361	
362	        impl->host_name.emplace(updated_host_name);
363	    }
364	
365	    /// FIXME Updating may take a long time because we cannot manage timeouts of getaddrinfo(...) and getnameinfo(...).
366	    /// DROP DNS CACHE will wait on update_mutex (possibly while holding drop_mutex)
367	    std::lock_guard lock(impl->update_mutex);
368	
369	    bool hosts_updated = updateCacheImpl(
370	        &DNSResolver::updateHost, impl->known_hosts, max_consecutive_failures, "Cached hosts not found: {}", "Cached hosts dropped: {}");
371	    updateCacheImpl(
372	        &DNSResolver::updateAddress,
373	        impl->known_addresses,
374	        max_consecutive_failures,
375	        "Cached addresses not found: {}",
376	        "Cached addresses dropped: {}");
377	
378	    LOG_DEBUG(log, "Updated DNS cache");
379	    return hosts_updated;
380	}
